function subjectFamily(name) {
      if (!name) return '';
      var n = String(name).trim();
      n = n.replace(/:\s*(Trilogy|Synergy)\s*$/i, '');     // Combined Science: Trilogy → Combined Science
      n = n.replace(/\s*\([^)]*\)\s*$/, '');                // (Geographical Themes) etc.
      n = n.replace(/\s+[AB]$/, '');                         // Geography A → Geography
      // Cross-board name aliases — same subject, different boards label it differently.
      if (/^food and nutrition$/i.test(n)) n = 'Food Preparation and Nutrition'; // WJEC
      return n.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
    }
